 public static class NodePolicy {
  public static string Country(string name){string n=name??"";var codes=new List<string>();
   var patterns=new Dictionary<string,string>{{"SG",@"新加坡|狮城|Singapore|🇸🇬|\bSG\b|SG[-_A-Z0-9]"},{"JP",@"日本|东京|大阪|Japan|Tokyo|🇯🇵|\bJP\b|JP[-_A-Z0-9]"},{"US",@"美国|洛杉矶|United States|Los Angeles|🇺🇸|\bUSA?\b|US[-_A-Z0-9]"},{"HK",@"香港|Hong Kong|Hongkong|🇭🇰|\bHK\b|HK[-_A-Z0-9]"},{"TW",@"台湾|台灣|Taiwan|🇹🇼|\bTW\b|TW[-_A-Z0-9]"},{"KR",@"韩国|韓國|Korea|🇰🇷|\bKR\b|KR[-_A-Z0-9]"},{"GB",@"英国|英國|United Kingdom|London|🇬🇧|\bUK\b|\bGB\b"},{"DE",@"德国|德國|Germany|🇩🇪|\bDE\b"},{"CA",@"加拿大|Canada|🇨🇦|\bCA\b"},{"AU",@"澳大利亚|澳洲|Australia|🇦🇺|\bAU\b"},{"FR",@"法国|法國|France|🇫🇷|\bFR\b"}};
   foreach(var pair in patterns)if(Regex.IsMatch(n,pair.Value,RegexOptions.IgnoreCase))codes.Add(pair.Key);return codes.Count==1?codes[0]:"";
  }
  public static string CountryText(string code){var names=new Dictionary<string,string>{{"SG","新加坡"},{"JP","日本"},{"US","美国"},{"HK","香港"},{"TW","台湾"},{"KR","韩国"},{"GB","英国"},{"DE","德国"},{"CA","加拿大"},{"AU","澳大利亚"},{"FR","法国"}};return names.ContainsKey(code)?names[code]:"未识别";}
