  public static string Leaf(Dictionary<string,NodeInfo> nodes,string name){var visited=new HashSet<string>();while(!String.IsNullOrEmpty(name)&&nodes.ContainsKey(name)&&visited.Add(name)){var n=nodes[name];if(n.IsLeaf)return name;if(n.Members.Length==0)return "";name=n.Selected;}return "";}
  public static string ActiveGroup(NetworkView view,Settings settings){if(view.Mode=="global")return "GLOBAL";if(view.Mode=="rule"&&view.RuleVerified)return view.RuleOwner;return "";}
  public static string BlockReason(NetworkView v,Settings s){if(s.Paused)return "守护已暂停";if(PausePolicy.Active(s,DateTime.UtcNow))return "自动恢复临时暂停，剩余 "+Math.Ceiling(PausePolicy.Remaining(s,DateTime.UtcNow)/60.0)+" 分钟";if(!v.Controller)return "控制接口未连接";if(!s.AutoSwitch)return "自动恢复未开启";if(v.Mode=="global"&&!s.AllowGlobalSwitch)return "全局恢复未授权";if(v.Mode!="rule"&&v.Mode!="global")return "当前模式不支持节点恢复";if(String.IsNullOrEmpty(v.Group)||!v.Nodes.ContainsKey(v.Group)||v.Nodes[v.Group].Type!="Selector")return "请选择可手动选择的策略组";if(v.Mode=="rule"&&!v.RuleVerified)return String.IsNullOrEmpty(v.RuleIssue)?"规则路径未确认":v.RuleIssue;if(ActiveGroup(v,s)!=v.Group)return "当前流量策略组与设置不一致";if(s.AllowCountryFallback){if(!CountryFallback.Supported(v.Country))return "当前节点不在日本 / 新加坡范围内";if(!CountryPolicy.ForCountry(v,s,v.Country).Contains(v.Node))return "当前节点被排除";return "";}if(String.IsNullOrEmpty(s.LockedCountry)||v.Country!=s.LockedCountry)return "当前节点不在锁定国家内";if(CountryPolicy.Effective(v,s).Length<2)return "至少勾选两个同国家候选节点";if(!CountryPolicy.Effective(v,s).Contains(v.Node))return "当前节点不在候选白名单内";return "";}
  public static List<NodeInfo> Eligible(NetworkView v,Settings s){if(!v.Nodes.ContainsKey(v.Group))return new List<NodeInfo>();return v.Nodes[v.Group].Members.Where(n=>n!=v.Node&&CountryPolicy.Effective(v,s).Contains(n)&&v.Nodes.ContainsKey(n)).Select(n=>v.Nodes[n]).Where(n=>n.IsLeaf&&n.Country==s.LockedCountry&&!String.IsNullOrEmpty(n.Country)).ToList();}
  public static string Rate(double bytes){if(bytes<0||Double.IsNaN(bytes)||Double.IsInfinity(bytes))return "—";if(bytes>=1024*1024)return (bytes/(1024*1024)).ToString("0.0")+" MB/s";if(bytes>=1024)return (bytes/1024).ToString("0.0")+" KB/s";return bytes.ToString("0")+" B/s";}
