  internal static object[] Array(Dictionary<string,object> d,string k){object o;if(!d.TryGetValue(k,out o)||o==null)return new object[0];var a=o as object[];if(a!=null)return a;var list=o as System.Collections.ArrayList;return list!=null?list.ToArray():new object[0];}
  internal static string Str(Dictionary<string,object> d,string k){object o;return d.TryGetValue(k,out o)?Convert.ToString(o):"";}
  internal static double Num(Dictionary<string,object> d,string k){double n;return Double.TryParse(Str(d,k),out n)?n:0;}
  public static bool TryDelay(Dictionary<string,object> data,out int delay){delay=-1;object raw;if(!data.TryGetValue("delay",out raw)||!(raw is int||raw is long||raw is double||raw is decimal||raw is float))return false;double value=Convert.ToDouble(raw);if(Double.IsNaN(value)||Double.IsInfinity(value)||value<0||value>6000)return false;delay=(int)value;return true;}
 }
 public sealed class RecoveryDecision {
  public int Failures;public DateTime LastSample=DateTime.MinValue,NextAttempt=DateTime.MinValue;public string Node="";public DateTime FirstFailureUtc=DateTime.MinValue;
  readonly Queue<KeyValuePair<DateTime,bool>> samples=new Queue<KeyValuePair<DateTime,bool>>();
  public void Reset(string node){Node=node;Failures=0;FirstFailureUtc=LastSample=DateTime.MinValue;samples.Clear();}
  public void Observe(string node,bool ok,DateTime now){Observe(node,ok,now,15);}
  public void Observe(string node,bool ok,DateTime now,int spacing){if(Node!=node)Reset(node);if((now-LastSample).TotalSeconds<spacing)return;LastSample=now;samples.Enqueue(new KeyValuePair<DateTime,bool>(now,ok));while(samples.Count>4||(samples.Count>0&&(now-samples.Peek().Key).TotalSeconds>90))samples.Dequeue();if(ok){Failures=0;FirstFailureUtc=DateTime.MinValue;}else{if(Failures==0)FirstFailureUtc=now;Failures++;}}
  public bool Ready(DateTime now,NetworkState state){return Ready(now,state,false);}
  public bool Ready(DateTime now,NetworkState state,bool fast){return (Failures>=(fast?2:3)||fast&&Failures>0&&samples.Count==4&&samples.Count(x=>!x.Value)==3&&(now-samples.Peek().Key).TotalSeconds<=90)&&now>=NextAttempt&&(now-Files.Date(state.LastSwitchUtc)).TotalSeconds>=(fast?45:180)&&(state.Switches??new List<string>()).Count(t=>(now-Files.Date(t)).TotalMinutes<(fast?10:30))<3;}
 }
