  void Tick(object unused){if(disposed||Interlocked.CompareExchange(ref busy,1,0)!=0)return;try{Settings s=engine.Config();if(!readOnly&&!String.IsNullOrEmpty(s.RecoveryPauseUntilUtc)&&!PausePolicy.Active(s,DateTime.UtcNow)){engine.Update(c=>c.RecoveryPauseUntilUtc="");s=engine.Config();}var v=Read(s);MaintainBinding(v,s);controllerDownSince=DateTime.MinValue;alerts.Resolve("controller");if(s.Paused)decision.Failures=0;
   if(!s.Paused&&DateTime.UtcNow>=probeDue&&!String.IsNullOrEmpty(v.Node)){v.Checking=true;View=v;var generic=Task.Run(()=>{int primary=Delay(v.Node,TargetA);return primary>=0?primary:Delay(v.Node,TargetB);});var services=ParallelServices(v.Node,s.AllowCountryFallback?2000:4000);int a=generic.Result,b=a;int serviceA=services.FirstResult,serviceB=services.SecondResult;bool recent=RecentTraffic(v.Node);if(recent){if(serviceA<0)serviceA=Delay(v.Node,ServiceA,4000);if(serviceB<0)serviceB=Delay(v.Node,ServiceB,4000);}if(disposed)return;v.Checking=false;v.ProbeKnown=true;v.ProbeOk=a>=0||b>=0||serviceA>=0||serviceB>=0;v.Delay=a>=0?a:b;v.ProbeUtc=DateTime.UtcNow.ToString("o");services.Uncertain=serviceA==-2||serviceB==-2;v.ChatGptProbeResult=serviceA;v.CodexProbeResult=serviceB;v.ServiceKnown=!services.Uncertain;v.ChatGptReachable=serviceA>=0;v.CodexReachable=serviceB>=0;v.ServiceProbeUtc=v.ProbeUtc;bool serviceOk=v.ChatGptReachable&&v.CodexReachable;bool partial=v.ChatGptReachable||v.CodexReachable;if(!services.Uncertain&&(partial||!recent))decision.Observe(v.Node,partial,DateTime.UtcNow,s.AllowCountryFallback?8:15);v.Failures=decision.Failures;probeDue=DateTime.UtcNow.AddSeconds(s.AllowCountryFallback?(serviceOk?10:4):(serviceOk?30:15));v.Message=serviceOk?"服务路径得到响应（不验证登录 / 对话）":"服务路径异常，复测 "+v.Failures+(s.AllowCountryFallback?" / 2":" / 3");
    if(!services.Uncertain&&(serviceOk||!partial))Record(v.Group,v.Node,serviceOk,v.Delay);if(!serviceOk)CaptureIncident(v,"服务路径探测异常");
    if(serviceOk)alerts.Resolve("unavailable");if(services.Uncertain)v.Message="控制请求结果未确认，不计为节点故障";if(recent&&!serviceOk)v.Message="探测异常，但仍有近期长连接传输，继续确认";if(!services.Uncertain&&!serviceOk&&!recent&&(routeSnapshot==null||SameRoute(v,routeSnapshot))&&decision.Ready(DateTime.UtcNow,state,s.AllowCountryFallback)){string reason=NodePolicy.BlockReason(v,s);if(reason.Length==0){View=v;Recover(v,s);}else v.Message="服务路径异常 · "+reason;}
   }
   if(Interlocked.Exchange(ref incidentRequested,0)!=0)CaptureIncident(v,"用户报告任务疑似卡住");

   if(s.Paused)v.Message="守护已暂停";else if(String.IsNullOrEmpty(v.Node))v.Message=v.Mode=="rule"?v.RuleIssue:"未识别当前节点";
   if(!String.IsNullOrEmpty(state.PendingCandidate)){v.Message="上次切换结果待核对，自动恢复已停止";}else alerts.Resolve("pending");
   v.Checking=false;View=v;
  }catch(Exception e){if(controllerDownSince==DateTime.MinValue)controllerDownSince=DateTime.UtcNow;trafficBaseline=false;decision.Failures=0;var oldClient=client as MihomoClient;if(oldClient!=null)oldClient.StopLog();client=null;catalogDue=DateTime.MinValue;Note("本机控制接口暂时不可达，已保留节点与会话。");View=new NetworkView{Message="本机控制接口未连接",Error=e is InvalidOperationException?e.Message:"状态读取失败，请重新检查。",UpdatedUtc=DateTime.UtcNow.ToString("o")};Thread.Sleep(1000);}finally{Interlocked.Exchange(ref busy,0);}}
  void PollRoute(object unused){if(disposed||Interlocked.CompareExchange(ref routeBusy,1,0)!=0)return;try{var active=client;if(active==null)return;var route=FreshRoute(engine.Config());route.RouteUtc=DateTime.UtcNow.ToString("o");if(!disposed&&active==client)routeSnapshot=route;}catch{}finally{Interlocked.Exchange(ref routeBusy,0);}}
  void PollFailures(object unused){if(disposed||readOnly||Interlocked.CompareExchange(ref logBusy,1,0)!=0)return;var active=client as MihomoClient;try{if(active==null)return;active.ReadWarnings(line=>{var v=View;DateTime now=DateTime.UtcNow;if(!Evidence23.Fresh(v.RouteUtc,now,8)||(now-Files.Date(state.LastSwitchUtc)).TotalSeconds<20)return;var failure=Evidence23.ParseFailure(line,v,now);if(failure==null||Evidence23.Relevant(linkFailure,v,now)&&(now-Files.Date(linkFailure.Utc)).TotalSeconds<10)return;linkFailure=failure;Journal.Event(v,"incident","相关连接失败线索："+failure.Kind,now,true);probeDue=DateTime.MinValue;},()=>logFeed="监听中（只提取相关失败线索）",()=>!disposed&&client==active);}catch{logFeed="失败日志暂不可用，仍保留主动探测";}finally{if(active!=null&&!disposed&&logFeed.StartsWith("监听中"))logFeed="日志流已结束，等待重连";Interlocked.Exchange(ref logBusy,0);}}
  internal static bool AdoptBinding(NetworkView v,Settings c){
   if(!c.MaintainRuleBinding||!c.AutoSwitch||!c.AllowCountryFallback||c.Paused||PausePolicy.Active(c,DateTime.UtcNow)||v.Mode!="rule"||!v.RuleVerified||String.IsNullOrEmpty(v.RuleRoot)||String.IsNullOrEmpty(v.RuleOwner)||!CountryFallback.Supported(v.Country)||CountryPolicy.Members(v,v.Group,"JP").Length==0||CountryPolicy.Members(v,v.Group,"SG").Length==0)return false;
   if(String.IsNullOrEmpty(c.RuleBindingRoot)||v.Nodes.ContainsKey(c.RuleBindingRoot))return false;
   c.RuleBindingRoot=v.RuleRoot;c.RuleBindingChild=v.RuleOwner;if(!v.Nodes.ContainsKey(c.ManagedGroup??""))c.ManagedGroup=v.RuleOwner;return true;
  }
  void MaintainBinding(NetworkView v,Settings c){if(!readOnly&&!disposed&&AdoptBinding(v,c)){engine.Update(saved=>{AdoptBinding(v,saved);});Note("订阅分组已变化，已保存实测确认的日新选择组；未改变节点或分流规则。");c=engine.Config();}if(readOnly||disposed||!c.MaintainRuleBinding||c.Paused||PausePolicy.Active(c,DateTime.UtcNow)||!c.AutoSwitch||!c.AllowCountryFallback||v.Mode!="rule"||!v.RuleVerified||v.RuleRoot!=c.RuleBindingRoot||v.Group==c.RuleBindingChild||DateTime.UtcNow<bindingDue)return;
   bindingDue=DateTime.UtcNow.AddMinutes(2);var plan=RuleRepair.Prepare(client);if(!plan.Ready||plan.Root!=c.RuleBindingRoot||plan.Child!=c.RuleBindingChild||plan.Node!=v.Node)return;
   // Reattach only the saved, user-enabled group while retaining the current service leaf.
   var result=RuleRepair.Apply(client,()=>!disposed&&!engine.Config().Paused&&!PausePolicy.Active(engine.Config(),DateTime.UtcNow)&&engine.Config().MaintainRuleBinding&&engine.Config().AutoSwitch&&engine.Config().AllowCountryFallback);
   if(result.Verified){Note("已恢复已保存的日新规则选择链，保留当前服务节点；共享组其他应用可能随组选择变化。");var fresh=FreshRoute(engine.Config());fresh.RouteUtc=DateTime.UtcNow.ToString("o");routeSnapshot=fresh;catalogDue=probeDue=DateTime.MinValue;decision.Reset(fresh.Node);}else Note("日新规则选择链未恢复；保留当前路线等待核对。");
  }
  ServiceSample ParallelServices(string node,int timeout){int a=-1,b=-1;Parallel.Invoke(()=>a=Delay(node,ServiceA,timeout),()=>b=Delay(node,ServiceB,timeout));return new ServiceSample{First=a>=0,Second=b>=0,FirstResult=a,SecondResult=b,Delay=Math.Max(a,b),RecentActivity=RecentTraffic(node),Uncertain=a==-2||b==-2};}
  void PollTraffic(object unused){if(disposed||Interlocked.CompareExchange(ref trafficBusy,1,0)!=0)return;try{IController active=client;if(active==null)return;var sample=tracker.Sample(active.Call("/connections","GET",null),DateTime.UtcNow);traffic=sample;PublishStatus();bool quiet=sample.Quiet(DateTime.UtcNow);if(quiet&&!quietNoted)CaptureIncident(View,"服务连接 3 分钟暂无新流量；不能据此判定断连");quietNoted=quiet;}catch{tracker.Reset();traffic=null;}finally{Interlocked.Exchange(ref trafficBusy,0);}}
  void PollDiagnostics(object unused){if(disposed||readOnly||Interlocked.CompareExchange(ref diagnosticBusy,1,0)!=0)return;try{var v=View;Journal.Observe(v,DateTime.UtcNow);var current=Automation;if(current.Active&&current.NeedsAttention&&!current.Notified){Emit("case-"+current.Id,"自动处理需要关注",current.Text);Journal.MarkNotified();}PublishStatus();}catch{}finally{Interlocked.Exchange(ref diagnosticBusy,0);}}
  public void ReportWorking(){if(readOnly)return;Journal.Event(View,"manual-report","用户标记：提示异常，但仍能正常使用",DateTime.UtcNow,true);}
  void PublishStatus(){if(disposed||readOnly||DateTime.UtcNow<statusDue)return;statusDue=DateTime.UtcNow.AddSeconds(5);try{var v=View;var c=engine.Config();var status=Evidence23.Describe(v,c,v.LinkFailure,DateTime.UtcNow);Files.Save("network-status.json",new {UpdatedUtc=DateTime.UtcNow.ToString("o"),v.Mode,v.Group,v.Node,v.RuleVerified,v.RuleRoot,v.RuleOwner,v.RuleSource,v.RuleEvidenceUtc,v.RuleIssue,v.RouteUtc,v.ServiceProbeUtc,v.TrafficUtc,Status=status.Title,Detail=status.Detail,AppResponseUtc=v.AppResponseUtc,AppResponseNode=v.AppResponseNode,DiagnosticsSession=Journal.Session,DiagnosticsEnabled=c.DiagnosticsEnabled,DiagnosticsError=Journal.Error,Automation=Automation,v.LogFeed,Coverage=Evidence23.Coverage(v,c),Wait=RecoveryWait,RelatedFailure=Evidence23.Relevant(linkFailure,v,DateTime.UtcNow),c.MaintainRuleBinding,c.AutoSwitch,c.AllowCountryFallback});}catch{}}
  public void ReportStall(){if(!readOnly)Journal.Event(View,"manual-report","用户报告任务超时或卡住",DateTime.UtcNow,true);linkFailure=new LinkFailure{UserReported=true,Node=View.Node,Group=View.Group,Utc=DateTime.UtcNow.ToString("o")};CaptureIncident(View,"用户报告卡顿，开始复测；不代表已确认节点故障");Interlocked.Exchange(ref incidentRequested,1);Request();}
  string HistoryKey(string group,string node){return (client==null?"":client.Identity)+CountryPolicy.Scope(group,node);}
  double Rank(string group,string node){NodeRecord r;return Reliability.Rank(state.ReliabilityHistory.TryGetValue(HistoryKey(group,node),out r)?r:null,DateTime.UtcNow);}
  void Record(string group,string node,bool ok,int delay){if(disposed)return;Reliability.Observe(state.ReliabilityHistory,HistoryKey(group,node),ok,delay,DateTime.UtcNow);if(state.ReliabilityHistory.Count>128)state.ReliabilityHistory=state.ReliabilityHistory.Take(128).ToDictionary(x=>x.Key,x=>x.Value);if(!readOnly)Files.Save("network-state.json",state);}
  void CaptureIncident(NetworkView v,string reason){if(readOnly||disposed)return;Journal.Event(v,"incident",reason,DateTime.UtcNow,true);var summary=new {Reason=reason,TimeUtc=DateTime.UtcNow.ToString("o"),Mode=v.Mode,Group=v.Group,Node=v.Node,CountryLabel=v.Country,Controller=v.Controller,GeneralProbe=v.ProbeKnown?(bool?)v.ProbeOk:null,ChatGpt=v.ServiceKnown?(bool?)v.ChatGptReachable:null,Codex=v.ServiceKnown?(bool?)v.CodexReachable:null,Connections=v.Connections,ServiceConnections=v.ServiceConnections,LastActivityUtc=v.LastServiceActivityUtc,RecoveryBlock=NodePolicy.BlockReason(v,engine.Config())};Files.Log("连接诊断："+new JavaScriptSerializer().Serialize(summary));}
  void Note(string message){LastAction=message;if(!readOnly&&message!=lastNote){Files.Log("节点恢复："+message);lastNote=message;}}
  bool LiveMatches(NetworkView expected,Settings settings){catalogDue=DateTime.MinValue;var live=Read(settings);return live.Mode==expected.Mode&&live.Group==expected.Group&&live.Node==expected.Node&&NodePolicy.BlockReason(live,settings).Length==0;}
  void SaveIntent(string group,string original,string candidate){state.Scope=client.Identity;state.PendingGroup=group;state.PendingOriginal=original;state.PendingCandidate=candidate;Files.Save("network-state.json",state);}
  void ClearIntent(){state.PendingGroup=state.PendingOriginal=state.PendingCandidate="";Files.Save("network-state.json",state);}
  void Select(string group,string node){client.Call("/proxies/"+Uri.EscapeDataString(group),"PUT",new {name=node});}
  string Selected(string group){return NodePolicy.Str(client.Call("/proxies/"+Uri.EscapeDataString(group),"GET",null),"now");}
  internal void Recover(NetworkView v,Settings settings){if(disposed||readOnly||NodePolicy.BlockReason(v,settings).Length>0||!String.IsNullOrEmpty(state.PendingCandidate))return;BeginRecovery();try{
   if(settings.AllowCountryFallback){RecoverCountries(v,settings);return;}
   // Two-target failure evidence is supplemented by direct local Internet health.
   if(!internet()){v.Message="本地网络未确认，保留节点";decision.NextAttempt=DateTime.UtcNow.AddMinutes(2);return;}
   var allCandidates=NodePolicy.Eligible(v,settings);var ranked=allCandidates.OrderByDescending(n=>Rank(v.Group,n.Name)).ThenBy(n=>n.Name).ToList();var candidates=ranked.Skip(state.ScanCursor%Math.Max(1,ranked.Count)).Concat(ranked.Take(state.ScanCursor%Math.Max(1,ranked.Count))).Take(6).ToList();state.ScanCursor=(state.ScanCursor+6)%Math.Max(1,ranked.Count);v.Message="正在复测同国家候选";View=v;
   foreach(var node in candidates){if(disposed||engine.Config().Paused)return;int a=Delay(node.Name,TargetA),b=Delay(node.Name,TargetB);if(disposed)return;int sa=Delay(node.Name,ServiceA),sb=Delay(node.Name,ServiceB);bool candidateOk=a>=0&&b>=0&&sa>=0&&sb>=0;Record(v.Group,node.Name,candidateOk,a);if(!candidateOk)continue;
    Settings fresh=engine.Config();if(NodePolicy.BlockReason(v,fresh).Length>0||!NodePolicy.Eligible(v,fresh).Any(n=>n.Name==node.Name)||!LiveMatches(v,fresh)){v.Message="设置或节点已变化，本次恢复已取消";return;}
    string original=Selected(v.Group);if(original!=v.Node){v.Message="当前选择已变化，本次恢复已取消";return;}SaveIntent(v.Group,original,node.Name);
    // Record the attempt before the write: crash/restart cannot reset the switch budget.
    state.LastSwitchUtc=DateTime.UtcNow.ToString("o");state.Switches=state.Switches.Where(t=>(DateTime.UtcNow-Files.Date(t)).TotalMinutes<30).ToList();state.Switches.Add(state.LastSwitchUtc);Files.Save("network-state.json",state);
    try{if(disposed||engine.Config().Paused){ClearIntent();return;}Select(v.Group,node.Name);if(Selected(v.Group)!=node.Name)throw new InvalidOperationException("选择回读不一致");
     // Probe the live selected group as well as its leaf. Do not delete existing connections.
     if(Delay(v.Group,TargetA)<0||Delay(v.Group,TargetB)<0||Delay(v.Group,ServiceA)<0||Delay(v.Group,ServiceB)<0||Selected(v.Group)!=node.Name)throw new InvalidOperationException("切换后路径验证失败");
     HistoryEvent(v,node.Name,node.Country,"同国节点恢复","成功");ClearIntent();v.Node=node.Name;v.Country=node.Country;v.ProbeKnown=v.ProbeOk=true;v.ServiceKnown=v.ChatGptReachable=v.CodexReachable=true;v.ChatGptProbeResult=v.CodexProbeResult=-3;v.ServiceProbeUtc=DateTime.UtcNow.ToString("o");v.Delay=a;v.ProbeUtc=DateTime.UtcNow.ToString("o");v.Failures=0;decision.Failures=0;v.Message="已恢复 · 保留已有连接";Note("同国家切换成功，未重启 Codex、未关闭连接。");catalogDue=DateTime.MinValue;probeDue=DateTime.UtcNow.AddSeconds(30);return;
    }catch{try{Record(v.Group,node.Name,false,a);if(Selected(v.Group)==node.Name){Select(v.Group,original);if(Selected(v.Group)!=original)throw new InvalidOperationException();ClearIntent();v.Message="验证失败，已恢复原选择";Note(v.Message);}else{v.Message="选择已被其他程序更改，停止自动恢复";Note(v.Message);}}catch{v.Message="切换结果待核对，自动恢复已停止";Note(v.Message);}HistoryEvent(v,node.Name,node.Country,"路径验证未通过",String.IsNullOrEmpty(state.PendingCandidate)?"已回退":"待核对");decision.NextAttempt=DateTime.UtcNow.AddMinutes(5);return;}
   }
   v.Message="同国家候选均未通过复测，2 分钟后重试";Note(v.Message);decision.NextAttempt=DateTime.UtcNow.AddMinutes(2);
   }finally{FinishProgress(v.Message);}
  }
  bool RecentTraffic(string node){var sample=traffic;string at;return sample!=null&&(DateTime.UtcNow-Files.Date(sample.UpdatedUtc)).TotalSeconds<6&&((sample.CriticalActivityByNode.TryGetValue(node,out at)&&(DateTime.UtcNow-Files.Date(at)).TotalSeconds<10)||(sample.AppResponseNode==node&&Evidence23.Fresh(sample.AppResponseUtc,DateTime.UtcNow,10)));}
  public void PauseRecovery(int minutes){engine.Update(c=>c.RecoveryPauseUntilUtc=minutes>0?DateTime.UtcNow.AddMinutes(minutes).ToString("o"):"");}
  void Emit(string key,string title,string text){if(readOnly||disposed||!alerts.Allow(key,DateTime.UtcNow))return;Alert=new UserAlert{Id=Interlocked.Increment(ref alertId),Title=title,Text=text};}
  void BeginRecovery(){recoveryBegan=decision.FirstFailureUtc==DateTime.MinValue?DateTime.UtcNow:decision.FirstFailureUtc;BeginPhase("准备恢复","",0);}
  int BeginPhase(string phase,string country,int total){int id=Interlocked.Increment(ref progressId);progress=new RecoveryProgress{Id=id,Active=true,Phase=phase,Country=country,Total=total,Unknown=total,StartedUtc=recoveryBegan.ToString("o")};return id;}
  void UpdateProgress(int phase,CountryAudit audit){lock(progressGate){var old=progress;if(old.Id!=phase||audit.Evidence.Count<old.Done)return;var updated=old.Copy();updated.Done=audit.Evidence.Count;updated.Healthy=audit.Evidence.Values.Count(x=>x.Verdict==ProbeVerdict.Healthy);updated.Failed=audit.Evidence.Values.Count(x=>x.Verdict==ProbeVerdict.ConfirmedFailed);updated.Unknown=updated.Total-updated.Healthy-updated.Failed;progress=updated;}}
  void FinishProgress(string result){lock(progressGate){if(!progress.Active)return;var done=progress.Copy();done.Active=false;done.Phase=result;progress=done;}}
  void HistoryEvent(NetworkView from,string target,string country,string reason,string result){if(readOnly||disposed)return;var row=new RecoveryRecord{AtUtc=DateTime.UtcNow.ToString("o"),From=from.Node,To=target,CountryFrom=from.Country,CountryTo=country,Mode=from.Mode,Group=from.Group,Reason=reason,Result=result,Seconds=Math.Max(0,(int)Math.Min(86400,(DateTime.UtcNow-recoveryBegan).TotalSeconds))};Journal.Event(from,"recovery",reason+"："+result+"；目标 "+target,DateTime.UtcNow,true);lock(historyGate){state.RecoveryHistory.Add(row);if(state.RecoveryHistory.Count>80)state.RecoveryHistory.RemoveRange(0,state.RecoveryHistory.Count-80);Files.Save("network-state.json",state);}}
  public RecoveryRecord[] History(){lock(historyGate)return state.RecoveryHistory.ToArray();}
  public void CheckExit(){if(readOnly||disposed||Interlocked.CompareExchange(ref geoBusy,1,0)!=0)return;ThreadPool.QueueUserWorkItem(x=>{try{if(client==null)client=MihomoClient.Discover(engine.Config());var before=FreshRoute(engine.Config());var previous=Exit;if(previous!=null&&previous.Node==before.Node&&(DateTime.UtcNow-Files.Date(previous.CheckedUtc)).TotalSeconds<60)return;string proxy=ProxyTools.Normalize(engine.View.ObservedProxy);if(proxy==null){Exit=new ExitSnapshot{Node=before.Node,Detail="代理入口尚未就绪"};return;}Exit=ExitInfo.Query(proxy,before,()=>FreshRoute(engine.Config()),()=>client.Call("/connections","GET",null));if(Exit.Conflict)Emit("geo-"+before.Node,"出口地区资料需要核对","此次地区资料与节点名称不同；未据此改变自动恢复规则。");}catch{Exit=new ExitSnapshot{Detail="出口资料未确认，保留当前连接"};}finally{Interlocked.Exchange(ref geoBusy,0);}});}
  public bool ExitBusy {get{return Interlocked.CompareExchange(ref geoBusy,0,0)!=0;}}
  void BindRules(NetworkView view){var route=ruleVerifier.Resolve(client,client.Call("/rules","GET",null),view.Nodes,engine.View.ObservedProxy,DateTime.UtcNow);view.RuleRoot=route.Root;view.RuleOwner=route.Owner;view.RuleVerified=route.Verified;view.RuleIssue=route.Issue;view.RuleSource=route.Source;view.RuleEvidenceUtc=route.EvidenceUtc;}
  NetworkView FreshRoute(Settings settings){client.Call("/version","GET",null);var fresh=new NetworkView{Controller=true,Mode=NodePolicy.Str(client.Call("/configs","GET",null),"mode"),Nodes=NodePolicy.Catalog(client.Call("/proxies","GET",null))};if(fresh.Mode=="rule")BindRules(fresh);fresh.Group=NodePolicy.ActiveGroup(fresh,settings);fresh.Node=NodePolicy.Leaf(fresh.Nodes,fresh.Group);fresh.Country=NodePolicy.Country(fresh.Node);return fresh;}
  bool SameRoute(NetworkView expected,NetworkView fresh){return expected.Mode==fresh.Mode&&expected.Group==fresh.Group&&expected.Node==fresh.Node&&(expected.Mode!="rule"||expected.RuleRoot==fresh.RuleRoot&&fresh.RuleVerified);}
  ServiceSample ProbeServices(NodeInfo node){return ParallelServices(node.Name,2000);}
  CountryAudit Audit(NetworkView route,string country,DateTime deadline){var names=CountryPolicy.Members(route,route.Group,country);int phase=BeginPhase("检查 "+NodePolicy.CountryText(country)+" 全部节点",country,names.Length);var audit=CountryFallback.Scan(country,names.Select(n=>route.Nodes[n]).ToArray(),ProbeServices,()=>!disposed&&!engine.Config().Paused&&!PausePolicy.Active(engine.Config(),DateTime.UtcNow)&&engine.Config().AllowCountryFallback,deadline,auditProgress=>UpdateProgress(phase,auditProgress),node=>ParallelServices(node.Name,4000));foreach(var sample in audit.Evidence.Values)if(sample.Verdict!=ProbeVerdict.Unknown)Record(route.Group,sample.Name,sample.Verdict==ProbeVerdict.Healthy,sample.Delay);return audit;}
  internal void RecoverCountries(NetworkView v,Settings settings){if(disposed||readOnly||!settings.AllowCountryFallback||NodePolicy.BlockReason(v,settings).Length>0||!String.IsNullOrEmpty(state.PendingCandidate))return;
   if(!internet()){v.Message="本地网络未确认，保留当前国家";decision.NextAttempt=DateTime.UtcNow.AddSeconds(15);return;}
   var fresh=FreshRoute(engine.Config());if(!SameRoute(v,fresh)){v.Message="当前路线已变化，本轮复测取消";return;}DateTime deadline=DateTime.UtcNow.AddSeconds(40);string country=v.Country;v.Message="并行复测 "+NodePolicy.CountryText(country)+" 全部节点";View=v;
   var current=Audit(fresh,country,deadline);state.LastCountryAudit=current;Files.Save("network-state.json",state);
   CountryEvidence active;if(current.Evidence.TryGetValue(v.Node,out active)&&active.Verdict==ProbeVerdict.Healthy){decision.Reset(v.Node);v.Failures=0;v.ProbeKnown=v.ProbeOk=v.ServiceKnown=v.ChatGptReachable=v.CodexReachable=true;v.ChatGptProbeResult=v.CodexProbeResult=-3;v.ServiceProbeUtc=v.ProbeUtc=DateTime.UtcNow.ToString("o");v.Message="当前国家节点已恢复，保持原选择";return;}
   var selectable=CountryPolicy.ForCountry(fresh,settings,country);var healthy=current.Evidence.Values.Where(x=>x.Name!=v.Node&&x.Verdict==ProbeVerdict.Healthy&&selectable.Contains(x.Name)).OrderByDescending(x=>Rank(v.Group,x.Name)).ToArray();
   if(healthy.Length>0){TryCountrySelection(v,healthy[0].Name,country,null);return;}
   if(!current.AllFailed(DateTime.UtcNow)){v.Message="本国仍有可达或未确认节点，不跨国切换";Note(v.Message);decision.NextAttempt=DateTime.UtcNow.AddSeconds(15);return;}
   Files.Log("国家复测："+new JavaScriptSerializer().Serialize(new {Country=country,AllNodesFailed=true,Nodes=current.Members,ConfirmedUtc=DateTime.UtcNow.ToString("o")}));
   string other=CountryFallback.Other(country);v.Message=NodePolicy.CountryText(country)+" 全部节点确认失败，检查 "+NodePolicy.CountryText(other);View=v;
   var alternate=Audit(fresh,other,deadline);selectable=CountryPolicy.ForCountry(fresh,engine.Config(),other);healthy=alternate.Evidence.Values.Where(x=>x.Verdict==ProbeVerdict.Healthy&&selectable.Contains(x.Name)).OrderByDescending(x=>Rank(v.Group,x.Name)).ToArray();
   if(healthy.Length==0){v.Message="日新节点暂无已确认可用候选，15 秒后复测";Note(v.Message);decision.NextAttempt=DateTime.UtcNow.AddSeconds(15);return;}
   TryCountrySelection(v,healthy[0].Name,other,current);
  }
  void TryCountrySelection(NetworkView v,string node,string country,CountryAudit crossProof){Settings settings=engine.Config();if(disposed||!settings.AllowCountryFallback||NodePolicy.BlockReason(v,settings).Length>0)return;
   var fresh=FreshRoute(settings);if(!SameRoute(v,fresh)||!CountryFallback.Supported(country)||!CountryPolicy.ForCountry(fresh,settings,country).Contains(node)){v.Message="节点或设置已变化，恢复已取消";return;}
   if(country!=v.Country&&(crossProof==null||crossProof.Country!=v.Country||!crossProof.AllFailed(DateTime.UtcNow)||!crossProof.SameMembers(CountryPolicy.Members(fresh,v.Group,v.Country)))){v.Message="全国家故障证据不完整或已过期，不跨国";Note(v.Message);decision.NextAttempt=DateTime.UtcNow.AddSeconds(8);return;}
   var candidate=ParallelServices(node,4000);if(!candidate.Healthy){v.Message="候选二次验证未确认，保留原节点";decision.NextAttempt=DateTime.UtcNow.AddSeconds(8);return;}string original=Selected(v.Group);if(original!=v.Node)return;BeginPhase("验证新节点路径",country,0);SaveIntent(v.Group,original,node);state.LastSwitchUtc=DateTime.UtcNow.ToString("o");state.Switches=state.Switches.Where(t=>(DateTime.UtcNow-Files.Date(t)).TotalMinutes<10).ToList();state.Switches.Add(state.LastSwitchUtc);Files.Save("network-state.json",state);
   try{settings=engine.Config();if(disposed||!settings.AllowCountryFallback||NodePolicy.BlockReason(v,settings).Length>0){ClearIntent();return;}Select(v.Group,node);var verified=ParallelServices(v.Group,4000);if(!verified.Healthy&&!disposed&&!engine.Config().Paused&&!PausePolicy.Active(engine.Config(),DateTime.UtcNow))verified=ParallelServices(v.Group,4000);var after=FreshRoute(engine.Config());if(Selected(v.Group)!=node||!verified.Healthy||after.Mode!=v.Mode||after.Group!=v.Group||after.Node!=node||(v.Mode=="rule"&&after.RuleRoot!=v.RuleRoot))throw new InvalidOperationException("路径验证失败");
    engine.Update(c=>{c.LockedCountry=country;c.AllowedNodes=CountryPolicy.ForCountry(fresh,c,country);});HistoryEvent(v,node,country,country!=v.Country?"原国家全部节点确认失败":"同国节点恢复","成功");ClearIntent();bool cross=country!=v.Country;v.Node=node;v.Country=country;v.ProbeKnown=v.ProbeOk=v.ServiceKnown=v.ChatGptReachable=v.CodexReachable=true;v.ChatGptProbeResult=v.CodexProbeResult=-3;v.ServiceProbeUtc=v.ProbeUtc=DateTime.UtcNow.ToString("o");v.Failures=decision.Failures=0;v.Message=cross?"原国家全部失败，已切换至 "+NodePolicy.CountryText(country):"已在同国家恢复";Note(v.Message+"；保留 Codex 进程及已有连接。");catalogDue=DateTime.MinValue;probeDue=DateTime.UtcNow.AddSeconds(20);
   }catch{try{Record(v.Group,node,false,-1);if(Selected(v.Group)==node){Select(v.Group,original);if(Selected(v.Group)!=original)throw new InvalidOperationException();ClearIntent();v.Message="路径验证失败，已回退原节点";}else v.Message="选择已发生外部变化，自动恢复停止";}catch{v.Message="恢复结果待核对，自动恢复停止";}HistoryEvent(v,node,country,"切换后服务路径未通过",String.IsNullOrEmpty(state.PendingCandidate)?"已回退":"待核对");Note(v.Message);decision.NextAttempt=DateTime.UtcNow.AddSeconds(45);}
  }
  public void Reconcile(){if(Interlocked.CompareExchange(ref busy,1,0)!=0)return;try{if(String.IsNullOrEmpty(state.PendingCandidate))return;if(client==null)client=MihomoClient.Discover(engine.Config());if(state.Scope!=client.Identity)throw new InvalidOperationException("控制接口已变化，保留待核对记录。");string selected=Selected(state.PendingGroup);if(selected!=state.PendingOriginal&&selected!=state.PendingCandidate)throw new InvalidOperationException("选择已发生外部变化，保留待核对记录。");ClearIntent();Note("已核对当前选择，恢复记录已确认。");catalogDue=probeDue=DateTime.MinValue;}catch(Exception e){Note(e is InvalidOperationException?e.Message:"核对失败，请重试。");}finally{Interlocked.Exchange(ref busy,0);}}
  public void RestartCore(){if(Interlocked.CompareExchange(ref busy,1,0)!=0){Note("监控正在检查，请稍后重试刷新内核。");return;}try{if(disposed||engine.Config().Paused){Note("守护已暂停，未重启代理内核。");return;}if(client==null)client=MihomoClient.Discover(engine.Config());client.Call("/restart","POST",new {path="",payload=""});Note("已请求刷新代理内核；正在等待控制接口恢复。");if(controllerDownSince==DateTime.MinValue)controllerDownSince=DateTime.UtcNow;trafficBaseline=false;decision.Failures=0;var oldClient=client as MihomoClient;if(oldClient!=null)oldClient.StopLog();client=null;catalogDue=probeDue=DateTime.MinValue;}catch{Note("内核刷新结果未确认，请等待状态恢复后核对。");}finally{Interlocked.Exchange(ref busy,0);}}
  public void Dispose(){disposed=true;if(diagnosticTimer!=null)diagnosticTimer.Dispose();Journal.Dispose();FinishProgress("已结束");if(timer!=null)timer.Dispose();if(trafficTimer!=null)trafficTimer.Dispose();if(routeTimer!=null)routeTimer.Dispose();if(logTimer!=null)logTimer.Dispose();var streamClient=client as MihomoClient;if(streamClient!=null)streamClient.StopLog();}
 }
}

